package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.dream.*; import com.wizzadrds.theworldremembers.memory.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import java.util.*;
public final class DreamGameTest { @GameTest public void sleepingNpcCanReceiveDream(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);var mm=MemoryManager.get(c.getLevel().getServer());mm.rememberEvent(v.getUUID(),UUID.randomUUID(),MemoryEventType.NPC_MARRIED,1,MemoryImportance.IMPORTANT);c.runAtTickTime(1,()->{var dm=DreamManager.get(c.getLevel().getServer());dm.generateForSleepingNpc(v.getUUID(),20,mm.memoriesOf(v.getUUID()));if(dm.latest(v.getUUID()).isEmpty()){c.fail("Dream was not generated");return;}c.succeed();});} @GameTest public void awakeNpcDoesNotDreamAutomatically(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);var mm=MemoryManager.get(c.getLevel().getServer());mm.rememberEvent(v.getUUID(),UUID.randomUUID(),MemoryEventType.NPC_MARRIED,1,MemoryImportance.IMPORTANT);c.runAtTickTime(1,()->{var dm=DreamManager.get(c.getLevel().getServer());TheWorldRemembers.processWorld(c.getLevel());if(dm.latest(v.getUUID()).isPresent()){c.fail("Awake NPC generated a dream");return;}c.succeed();});}}
